entries[360826] = { ["name"] = "Blutung", ["text"] = "100 Meter Reichweite\nSofort\nBenötigt Nahkampfwaffe\nSchneidet einem Gegner ein Todesmal ein, das ihm (320% der Angriffskraft) Blutungsschaden im Verlauf von 16 Sek. zufügt. Solange das Mal besteht, werden 'Erdrosseln', 'Blutung' und Eure angewendeten tödlichen Gifte bei diesem Ziel dupliziert, was 100% des normalen Schadens verursacht." }
entries[360827] = { ["name"] = "Sengende Schuppen", ["text"] = "25 Meter Reichweite\nSofort 30 sek. Abklingzeit\nSchützt einen Verbündeten mit 15 explosiven Drachenschuppen, was seine Rüstung um 20% Eurer eigenen Rüstung erhöht.\n\nNahkampfangriffe gegen das Ziel lassen 1 Schuppe explodieren, was allen Gegnern in seiner Nähe [[Quellwert] * 0.3 * (1 + Vielseitigkeit) * Prozentualer Schaden] Vulkanschaden zufügt. Dieser Schaden kann nur einmal alle paar Sekunden auftreten.\n\nMit 'Sengende Schuppen' kann nur jeweils ein Ziel gleichzeitig belegt werden. Wird auf das Ziel Eures Gegners gewirkt, falls dieser eines hat.", ["unresolvedValues"] = true }
entries[360828] = { ["name"] = "Sengende Schuppen", ["text"] = "100 Meter Reichweite\nSofort\nSchützt einen Verbündeten mit 15 explosiven Drachenschuppen, was seine Rüstung um 20% Eurer eigenen Rüstung erhöht.\n\nNahkampfangriffe gegen das Ziel lassen 1 Schuppe explodieren, was allen Gegnern in seiner Nähe [[Quellwert] * 0.3 * (1 + Vielseitigkeit) * Prozentualer Schaden] Vulkanschaden zufügt. Dieser Schaden kann nur einmal alle paar Sekunden auftreten.\n\nMit 'Sengende Schuppen' kann nur jeweils ein Ziel gleichzeitig belegt werden. Wird auf das Ziel Eures Gegners gewirkt, falls dieser eines hat.", ["unresolvedValues"] = true }
