entries[360952] = { ["name"] = "Koordinierter Angriff", ["text"] = "40 Meter Reichweite\nSofort 2 min Abklingzeit\nIhr und Euer Begleiter stürmt auf Euren Gegner zu, was diesem insgesamt [((200% der Angriffskraft)) + ((200% der Angriffskraft) * 0.6)] körperlichen Schaden zufügt. Der Bund mit Eurem Begleiter wird anschließend für 20 Sek. gestärkt, wodurch Ihr und Euer Begleiter 20% mehr Schaden verursacht.\n\nWährend 'Koordinierter Angriff' aktiv ist, wird die Chance von 'Tötungsbefehl', seine Abklingzeit abzuschließen, um 15% erhöht." }
entries[360953] = { ["name"] = "Darbender Seelendetritus", ["text"] = "Sofort\nWenn 'Geißelnder Obolus' Seelensplitter erzeugt, wird 8 Sek. lang Eure Bewegungsgeschwindigkeit um 100% und Eure kritische Trefferchance um 45% erhöht. Wenn 'Geißelnder Obolus' abläuft, wird stattdessen Eure Bewegungsgeschwindigkeit um 33% und Eure kritische Trefferchance um 15% erhöht." }
