entries[361709] = { ["name"] = "Ruf der Wildnis", ["text"] = "100 Meter Reichweite\nSofort\nIhr lasst den Ruf der Wildnis ertönen und beschwört so für 20 Sek. 2 Eurer aktiven Begleiter. Während dieser Zeit erscheint alle 4 Sek. ein zufälliger Begleiter aus Eurem Stall, der Euer Ziel 6 Sek. lang angreift.\n\nJedes Mal, wenn 'Ruf der Wildnis' ein Tier beschwört, wird die Abklingzeit von 'Stachelpfeil' und 'Tötungsbefehl' um 25% verringert." }
